/**
 * The official ETHQR brand marks, embedded as data URLs.
 *
 * PROVENANCE: both are cropped from the merchant-card template artwork in
 * EthSwitch's "ETHQR Brand Usage Standard & Identity Guideline" (Dec 2024),
 * https://ethswitch.com/wp-content/uploads/2024/12/ETHQR-Brand-Usage-Standard-Identity-Guideline.pdf
 * — they are the real marks, not redrawn approximations. Replace them with
 * vector originals if EthSwitch ever publishes the SVG/EPS; nothing about
 * the call sites needs to change.
 *
 * WHY DATA URLs RATHER THAN `import logo from './x.png'`:
 *
 * A Vite asset import over the 4KB inline limit becomes a URL that is
 * fetched at render time. This card is rasterised by html2canvas for the
 * mobile PDF export and re-laid-out by the browser's print pipeline, and in
 * both cases an <img> whose bytes have not arrived yet is captured as a
 * blank box — silently, and only on the printed artefact, while the
 * on-screen preview looks perfect. Inlining removes the fetch entirely, the
 * same reason the merchant logo and the payment QR are both converted to
 * data URLs before they reach the export path (see StandeeStudio).
 *
 * The two marks print at roughly 338 and 450 DPI at A5 trim, so they are
 * genuine print assets rather than screen-resolution stand-ins.
 *
 * GENERATED FILE — do not hand-edit the base64.
 */

/** The ETHQR wordmark: gold "ETH", the flag swoosh, navy "QR", and the tagline. */
export const ETHQR_LOGO_SRC =
  'data:image/png;base64,';

/** The "Powered by | ETHSWITCH" lockup, as the standard sets it: dark on a light ground. */
export const ETHSWITCH_POWERED_BY_SRC =
  'data:image/png;base64,';

/**
 * The acquiring wallet's mark for the "Acquired by" slot — what the
 * guideline leaves as a "BANK/PSP LOGO" placeholder, because the acquirer
 * supplies it rather than EthSwitch.
 *
 * The official green wordmark, from assets/mpesa-logo.png in this repo,
 * trimmed to its ink. Its ground is TRANSPARENT, so it composites onto the
 * white footer without carrying a field of its own.
 *
 * It briefly was a 130px crop crudely lifted from a sample card — white ink
 * on the red band it happened to sit on, so it had to keep that red field
 * and printed at roughly 132 DPI. This asset is ~362 DPI at the same
 * printed size.
 */
export const MPESA_BADGE_SRC =
  'data:image/png;base64,';

/** Intrinsic pixel sizes, so call sites can preserve each mark's aspect ratio. */
export const ETHQR_LOGO_ASPECT = 533 / 154;
export const ETHSWITCH_POWERED_BY_ASPECT = 625 / 80;
export const MPESA_BADGE_ASPECT = 439 / 115;
